/dts-v1/;

#include <arm/armv8-a/cortex_a53.dtsi>
#include <dt-bindings/interrupt-controller/arm-gic.h>
#include <dt-bindings/interrupt-controller/arm-gicv3.h>
#include <dt-bindings/clock/qemu_clock.h>

/ {
    model = "QEMU Cortex-A53";
    compatible = "qemu,cortex-a53";

    aliases {
        uart-0 = &uart0;
        uart-1 = &uart1;
        gpio-0 = &gpio0;
        gpio-1 = &gpio1;
    };

    chosen {
        zephyr,smp = <&smp>;
        zephyr,console = &uart0;
        zephyr,shell-uart = &uart0;
        zephyr,sram = &sram0;
        zephyr,code-partition = &flash0;
    };

    cpus {
        #address-cells = <1>;
        #size-cells = <0>;

        cpu@0 {
            compatible = "arm,cortex-a53";
            reg = <0>;
            clock-frequency = <1000000000>;
            cpu-power-domain = <&cpu_pd0>;
        };

        cpu@1 {
            compatible = "arm,cortex-a53";
            reg = <1>;
            clock-frequency = <1000000000>;
            cpu-power-domain = <&cpu_pd1>;
        };
    };

    smp: smp {
        compatible = "zephyr,smp";
        cpu-release-addr = <0x80000000>; /* Default for QEMU */
    };

    memory@40000000 {
        device_type = "memory";
        reg = <0x40000000 0x40000000>; /* 1GB */
    };

    sram0: memory@80000000 {
        device_type = "memory";
        reg = <0x80000000 0x10000000>; /* 256MB */
    };

    flash0: flash@0 {
        compatible = "jedec,spi-nor";
        reg = <0x0 0x1000000>; /* 16MB */
        erase-block-size = <0x10000>;
        write-block-size = <0x1>;
        partitions {
            compatible = "fixed-partitions";
            #address-cells = <1>;
            #size-cells = <1>;

            partition@0 {
                label = "flash_primary";
                reg = <0x0 0x1000000>;
            };
        };
    };

    soc {
        compatible = "simple-bus";
        #address-cells = <2>;
        #size-cells = <2>;
        ranges;

        gic: interrupt-controller@8000000 {
            compatible = "arm,gic-v3";
            reg = <0x0 0x8000000 0x0 0x100000 0x0 0x8010000 0x0 0x100000>;
            interrupt-cells = <3>;
            interrupt-controller;
            #interrupt-cells = <3>;
            arm,gic-cpu-mask = <0xf>; /* 4 CPUs */
            arm,gic-ppi-irqs = <GIC_PPI_LPT_PHYS_TIMER IRQ_TYPE_EDGE_RISING>,
                               <GIC_PPI_VIRT_TIMER IRQ_TYPE_EDGE_RISING>;
        };

        timer: timer@9000000 {
            compatible = "arm,armv8-timer";
            reg = <0x0 0x9000000 0x0 0x1000>;
            interrupts = <GIC_SPI 0 IRQ_TYPE_LEVEL_HIGH>;
        };

        uart0: uart@90000000 {
            compatible = "arm,pl011";
            reg = <0x0 0x90000000 0x0 0x1000>;
            interrupts = <GIC_SPI 1 IRQ_TYPE_LEVEL_HIGH>;
            clocks = <&qemu_clock 0>;
        };

        uart1: uart@90000001 {
            compatible = "arm,pl011";
            reg = <0x0 0x90000001 0x0 0x1000>;
            interrupts = <GIC_SPI 2 IRQ_TYPE_LEVEL_HIGH>;
            clocks = <&qemu_clock 0>;
        };

        gpio0: gpio@90000002 {
            compatible = "arm,primecell-gpio";
            reg = <0x0 0x90000002 0x0 0x1000>;
            interrupts = <GIC_SPI 3 IRQ_TYPE_LEVEL_HIGH>;
            gpio-cells = <2>;
            #gpio-cells = <2>;
        };

        gpio1: gpio@90000003 {
            compatible = "arm,primecell-gpio";
            reg = <0x0 0x90000003 0x0 0x1000>;
            interrupts = <GIC_SPI 4 IRQ_TYPE_LEVEL_HIGH>;
            gpio-cells = <2>;
            #gpio-cells = <2>;
        };

        qemu_clock: qemu-clock {
            compatible = "qemu,clock";
            #clock-cells = <1>;
        };
    };

    cpu_pd0: cpu-power-domain@0 {
        compatible = "arm,power-domain";
        reg = <0>;
    };

    cpu_pd1: cpu-power-domain@1 {
        compatible = "arm,power-domain";
        reg = <1>;
    };
};
